sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    const record = event.payload; // or api.data.<your_data_resource>.data, depending on setup
    const title = record.record.number.value || record.short_description; // whatever field you want
    helpers.screen.updateStatus({
        title: title
    });

}
